    const ref = this.dialog.open(Calendar, {
      data,
      injector: this.injector,
      ariaModal: true,
      ariaLabelledBy: titleId,
      autoFocus: false,
      restoreFocus: this.opener().nativeElement,
      hasBackdrop: true,
      backdropClass: 'app-backdrop',
      panelClass: sheet ? 'app-sheet' : 'app-popover',
      positionStrategy: panelPositionStrategy(this.injector, origin, sheet),
      disableAnimations: true,
    });
    ref.closed.subscribe((iso) => {
      this.calendarOpen.set(false);
      if (typeof iso === 'string') this.value.set(iso);
      this.touch.emit();
    });
  }
}
<input
  #box
  type="text"
  inputmode="numeric"
  autocomplete="off"
  class="input box"
  placeholder="dd/mm/aaaa"
  [class.input--icon]="hasIcon()"
  [id]="controlId()"
  [value]="text()"
  [attr.aria-required]="ariaRequired()"
  [attr.aria-invalid]="ariaInvalid() ? 'true' : null"
  [attr.aria-describedby]="ariaDescribedby()"
  (input)="onInput($event)"
  (blur)="onBlur()"
/>
<button #opener type="button" class="secondary opener" [attr.aria-label]="'Elegir fecha: ' + config().label" (click)="open()">
  <svg lucideCalendarDays></svg>
</button>
<div class="calendar" #root [class.calendar--sheet]="data.sheet">
  <div class="head">
    <span class="title" [id]="data.titleId" aria-live="polite">{{ title() }}</span>
    <div class="controls">
      <button type="button" class="secondary years" [attr.aria-expanded]="choosingYear()" (click)="toggleYears()">
        <svg lucideCalendarDays></svg>
        <span>Elegir año</span>
      </button>
      <button type="button" class="secondary" aria-label="Mes anterior" (click)="moveMonth(-1)">
        <svg lucideChevronLeft></svg>
      </button>
      <button type="button" class="secondary" aria-label="Mes siguiente" (click)="moveMonth(1)">
        <svg lucideChevronRight></svg>
      </button>
    </div>
  </div>

  @if (choosingYear()) {
    <ul ngListbox class="year-list" focusMode="roving" selectionMode="explicit" aria-label="Año" [wrap]="false" [value]="selectedYear()" (valueChange)="pickYear($event)">
      @for (year of years(); track year) {
        <li ngOption class="year" [value]="year" [label]="'' + year">{{ year }}</li>
      }
    </ul>
  } @else {
    <table class="grid" role="grid" [attr.aria-labelledby]="data.titleId">
      <thead>
        <tr>
          @for (name of grid().weekdays; track $index) {
            <th role="columnheader" scope="col" class="weekday" [attr.aria-label]="name">
              <span aria-hidden="true">{{ short[$index] }}</span>
            </th>
          }
        </tr>
      </thead>
      <tbody>
        @for (week of grid().weeks; track $index) {
          <tr>
            @for (cell of week; track $index) {
              @if (cell; as day) {
                <td
                  role="gridcell"
                  class="day"
                  [class.day--selected]="day.selected"
                  [class.day--disabled]="day.disabled"
                  [attr.tabindex]="day.iso === focused() ? 0 : -1"
                  [attr.aria-label]="day.name"
                  [attr.aria-selected]="day.selected ? 'true' : 'false'"
                  [attr.aria-disabled]="day.disabled ? 'true' : null"
                  (click)="choose(day.iso)"
                  (keydown)="onGridKeydown($event, day.iso)"
                >
                  {{ day.day }}
                </td>
              } @else {
                <td role="presentation" aria-hidden="true"></td>
              }
            }
          </tr>
        }
      </tbody>
    </table>
  }

  <button type="button" class="secondary close" (click)="close()">
    <svg lucideX></svg>
    <span>Cerrar</span>
  </button>
</div>

