    if (/(?<![\w.-])-?(?:\d+\.?\d*|\.\d+)(px|rem|em|ch|vw|vh)(?![\w-])/i.test(clean)) add('length', where);
    if (/(?<![\w.-])(?:\d+\.?\d*|\.\d+)(ms|s)(?![\w-])/i.test(clean)) add('duration', where);
