import { Component, inject } from '@angular/core';
import { Router, RouterLink } from '@angular/router';
import { CountryStore } from '../../core/country-store';
import { LucideChevronRight, LucideReceipt, LucideShieldCheck, LucideUserRound } from '@lucide/angular';
import { CountryFlag } from '../../shared/country-flag';
import { countryVisuals } from '../../shared/country-visuals';
import { LoadError } from '../../shared/load-error';
import { SiteHeader } from '../../shared/site-header';
import { WIZARD_STEPS } from '../../shared/step-indicator';

/** What each wizard step is about (spec 8.1, US-04-AC-29); the names come from the step indicator. */
const STEP_DESCRIPTIONS = ['Cuéntanos sobre ti y tu vehículo.', 'Compara coberturas y precios.', 'Revisa, acepta los términos y paga.'];

/**
 * Root address `/`: the app header, one link per published country (ADR-0001) and a short "how it
 * works" list of the three steps (US-04-BR-20). No detection from IP or locale.
 */
@Component({
  selector: 'app-country-chooser-page',
  imports: [RouterLink, LoadError, CountryFlag, SiteHeader, LucideChevronRight, LucideUserRound, LucideShieldCheck, LucideReceipt],
  templateUrl: './country-chooser-page.html',
  styleUrl: './country-page.css',
})
export class CountryChooserPage {
  protected readonly countries = inject(CountryStore);
  private readonly router = inject(Router);
  protected readonly steps = WIZARD_STEPS.map((step, i) => ({ ...step, description: STEP_DESCRIPTIONS[i] }));

  constructor() {
    void this.countries.ensureLoaded();
  }

  /** The accent key of a country card (a key of `[data-card-accent]` in `tokens.css`), or null. */
  protected accentOf(code: string): string | null {
    return countryVisuals(code).accent;
  }

  protected async retry(): Promise<void> {
    await this.countries.reload();
    await this.router.navigateByUrl(this.router.url, { onSameUrlNavigation: 'reload' });
  }
}
EOF
cat > country-chooser-page.html <<'EOF'
<app-site-header />
<main class="page page--chooser" animate.enter="page-enter" [attr.aria-busy]="countries.status() === 'loading' ? 'true' : null">
  <h1 tabindex="-1">Elige tu país</h1>
  <p class="lead">Cotiza el seguro de tu auto en pocos minutos. Elige el país donde está matriculado tu vehículo para ver los planes y precios disponibles.</p>
  @switch (countries.status()) {
    @case ('error') {
      <app-load-error message="No pudimos cargar la lista de países. Intenta de nuevo." (retry)="retry()" />
    }
    @case ('ready') {
      <ul class="list">
        @for (country of countries.countries(); track country.code) {
          <li>
            <a class="link" [attr.data-card-accent]="accentOf(country.code)" [routerLink]="['/', country.code.toLowerCase(), 'datos']">
              <app-country-flag [code]="country.code" [large]="true" />
              <span class="link__name">{{ country.name }}</span>
              <svg lucideChevronRight class="link__chevron"></svg>
            </a>
          </li>
        }
      </ul>
    }
    @default {
      <p role="status" class="visually-hidden">Cargando…</p>
      <div class="list" aria-hidden="true">
        <span class="skeleton skeleton--field"></span>
        <span class="skeleton skeleton--field"></span>
      </div>
    }
  }
  <section class="how">
    <h2>Cómo funciona</h2>
    <ol class="how__steps">
      @for (step of steps; track step.n) {
        <li class="how__step">
          <span class="how__icon" aria-hidden="true">
            @switch (step.n) {
              @case (1) {
                <svg lucideUserRound></svg>
              }
              @case (2) {
                <svg lucideShieldCheck></svg>
              }
              @default {
                <svg lucideReceipt></svg>
              }
            }
          </span>
          <span class="how__text">
            <strong class="how__name">{{ step.label }}</strong>
            <span class="how__description">{{ step.description }}</span>
          </span>
        </li>
      }
    </ol>
  </section>
</main>
EOF

