  color: var(--color-text-muted);
}
.link:focus-visible {
  border-color: var(--color-card-accent);
}
.link:focus-visible .link__chevron {
  color: var(--color-card-accent);
}
@media (hover: hover) {
  .link:hover {
    background: var(--color-surface-hover);
    border-color: var(--color-card-accent);
